import{_ as i,c as t,o,af as a}from"./chunks/framework.CpuDhtGM.js";const p=JSON.parse('{"title":"检查清单","description":"","frontmatter":{},"headers":[],"relativePath":"value-investing/value-investing/checklist.md","filePath":"value-investing/value-investing/checklist.md","lastUpdated":1766040972000}'),r={name:"value-investing/value-investing/checklist.md"};function s(e,l,u,n,h,c){return o(),t("div",null,[...l[0]||(l[0]=[a('<h1 id="检查清单" tabindex="-1">检查清单 <a class="header-anchor" href="#检查清单" aria-label="Permalink to &quot;检查清单&quot;">​</a></h1><h2 id="投资的检查清单思维" tabindex="-1">投资的检查清单思维 <a class="header-anchor" href="#投资的检查清单思维" aria-label="Permalink to &quot;投资的检查清单思维&quot;">​</a></h2><h3 id="一、入市之前的自我检查清单" tabindex="-1">一、入市之前的自我检查清单 <a class="header-anchor" href="#一、入市之前的自我检查清单" aria-label="Permalink to &quot;一、入市之前的自我检查清单&quot;">​</a></h3><ol><li>是否具备了完善的投资体系</li><li>是否具备必要的知识结构</li><li>是否具备合适的世界观、价值观、人生观和性格</li><li>是否做好了财务准备</li></ol><h3 id="二、公司研究阶段的检查清单" tabindex="-1">二、公司研究阶段的检查清单 <a class="header-anchor" href="#二、公司研究阶段的检查清单" aria-label="Permalink to &quot;二、公司研究阶段的检查清单&quot;">​</a></h3><ul><li><ol><li>公司过去多年的财务数据如何，有无重大疑问，财务表现是否优秀</li></ol><ul><li><ol><li>盈利能力指标：历年的 ROE 情况、毛利率、费用率和净利润率。</li></ol></li><li><ol start="2"><li>成长能力指标：历年的营收和扣非净利润的增长率。</li></ol></li><li><ol start="3"><li>现金流状况指标：经营活动现金流量净额与净利润的比值、应收账款占营业收入的比重、预收账款占营业收入的比重、自由现金流等。</li></ol></li><li><ol start="4"><li>运营能力指标：总资产周转率、应收账款周转天数、存货周转天数。</li></ol></li><li><ol start="5"><li>财务安全性指标：资产负债率、流动比率、速动比率、股票质押比例等。</li></ol></li><li><ol start="6"><li>财务数据的稳定性：企业经营是大起大落还是平稳增长。</li></ol></li><li><ol start="7"><li>回报股东的能力和意愿：历年融资和分红情况。</li></ol></li><li><ol start="8"><li>各种财务数据的同行业比较。</li></ol></li><li>ROE 是财务指标中最重要的指标。可以利用杜邦分析工具将企业财务数据统一起来，理解 ROE 的来源和变化的原因。</li></ul></li><li><ol start="2"><li>公司的商业模式是什么样的</li></ol><ul><li><ol><li>公司的客户是谁？</li></ol></li><li><ol start="2"><li>公司提供什么样的产品和服务？</li></ol></li><li><ol start="3"><li>公司的价值主张是什么？</li></ol></li><li><ol start="4"><li>解决了客户什么样的需求和痛点？公司内外部价值链是怎样的？</li></ol></li><li><ol start="5"><li>公司的盈利模式是怎样的？</li></ol></li><li><ol start="6"><li>公司所从事业务的生意特性是怎样的？</li></ol></li><li><ol start="7"><li>公司的自由现金流状况如何?</li></ol></li></ul></li><li><ol start="3"><li>公司未来的成长空间大小，成长动力是什么</li></ol><ul><li>随着行业增长销量的增加、占领更多的市场份额、扩展更多的地域、产品提价、产品结构升级、开发新产品、进入新的业务领域、收购兼并等。</li></ul></li><li><ol start="4"><li>公司有没有宽阔的护城河，体现在哪些方面</li></ol><ul><li>“波特五力分析”、护城河分析</li></ul></li><li><ol start="5"><li>公司的管理层是否德才兼备</li></ol></li><li><ol start="6"><li>公司的治理结构如何</li></ol><ul><li>公司的主要股东是谁？实际控制人是谁？公司是国企还是民企？管理层和主要骨干有没有持股？股权质押情况？公司制度化运作还是高度依赖企业家个人？</li></ul></li><li><ol start="7"><li>公司的企业文化如何</li></ol></li><li><ol start="8"><li>公司存在哪些劣势，未来可能存在哪些风险，有哪些负面因素</li></ol><ul><li>思考公司存在的负面因素：公司有哪些劣势或软肋?关于公司有哪些负面观点、负面消息，是否影响公司的投资价值?公司发展可能存在哪些风险?未来有什么原因可能会导致公司衰落甚至倒闭?如果出现最差的情况，公司能否维持生存和发展?</li></ul></li><li><ol start="9"><li>对公司的定性分析能否解释公司过往的经营业绩</li></ol><ul><li>对于财务数据优秀的公司，重点在于理解其过往为何而优秀，才有助于判断未来能否继续优秀或者更加优秀</li></ul></li></ul><h3 id="三、买入阶段的检查清单" tabindex="-1">三、买入阶段的检查清单 <a class="header-anchor" href="#三、买入阶段的检查清单" aria-label="Permalink to &quot;三、买入阶段的检查清单&quot;">​</a></h3><p>交易阶段的检查清单的任务是<strong>拒绝买入</strong>，拒绝不够安全的买入机会。① 尽可能以较低的成本获得更多的股权份额。② 为复杂多变的未来预留准备。</p><ul><li><ol><li>当前市场估值情况如何</li></ol><ul><li>市场估值整体只有一定的参考价值，一般来说市场萧条时机会更多，大多数公司无论好坏估值均会下降，但不代表具体公司有投资价值。</li></ul></li><li><ol start="2"><li>当前公司估值情况如何</li></ol><ul><li>公司历史估值和当前估值也只有参考价值。估值高低也不能简单看市盈率、市净率、市销率等指标，要回归到现金流折现这一原点。</li></ul></li><li><ol start="3"><li>当前公司基本面再分析</li></ol><ul><li>当前公司基本面与研究阶段相比是否已发生重大变化？</li><li>正面因素是否仍然存在但被忽视？</li><li>负面信息是否已被股价体现甚至过度体现？</li></ul></li><li><ol start="4"><li>当前价位下买入多少仓位</li></ol><ul><li>对一只标的买入仓位的大小，取决于我们对这家公司的“确定性”有多大把握</li><li>也取决于当前估值下，预期收益率的“弹性”有多大。</li><li>在能力圈范围内，考虑个人机会成本，给确定性高、弹性大的标的建立更大的仓位。</li><li>同时，仓位管理应有容错机制，保证即使完全看错，也能做到损失可控，不至于伤筋动骨。</li></ul></li><li><ol start="5"><li>当前价位买入后的加仓/持有预案</li></ol><ul><li>是否有短期内下跌/上涨 10%、20%、30%、50%等情况的应对方案?</li></ul></li><li><ol start="6"><li>买入前再次检查</li></ol><ul><li>对公司的研究是否已经足够彻底，有没有可能忽视的重大信息？</li><li>可以持仓的期限，是否愿意持有这家公司十年？</li><li>仓位是否合理，如果该笔买入的本金完全损失，是否可以承受？</li></ul></li><li><ol start="7"><li>检查买入动作是否受到心理偏误的影响</li></ol><ul><li>是否仅仅因为股价“正在”上涨或“已经”下跌而买入？</li><li>是否仅仅因为股价“已经”上涨或“正在”下跌而拒绝买入？</li><li>买入动作是否受到了价格/PE/PB 锚定效应的心理影响?</li></ul></li></ul><h3 id="四、持有阶段的检查清单" tabindex="-1">四、持有阶段的检查清单 <a class="header-anchor" href="#四、持有阶段的检查清单" aria-label="Permalink to &quot;四、持有阶段的检查清单&quot;">​</a></h3><p>持有阶段的检查清单，任务是<strong>拒绝卖出</strong>。解决卖出的标准问题。不触发卖出即为持有。牢记股权是目的，<strong>现金是手段。卖出是被动行为—不得不卖出（股权思维）​，而非主动行为—“落袋为安”或者“截断亏损”​（现金思维）​。</strong></p><ul><li><ol><li>持续关注公司的经营状况，是按照预期进展，还是变得更好或变得更坏</li></ol><ul><li>对于持仓的公司，我们应该定期体检。</li><li>平日要关注公司新闻等信息，季报、半年报、年报出来后持续跟踪其经营状况</li><li>还可以关注行业信息、竞争对手信息以及其他投资者的思考。当然不要在意短期业绩，要关注对公司具有长期影响的因素。</li></ul></li><li><ol start="2"><li>是否触发了卖出标准</li></ol><ul><li>仅仅基于现价与买入成本价差距做出的卖出决策都是逻辑错误的。</li><li>卖出的标准有且仅有四个。 <ul><li><ol><li>看错了。如果我们发现当时的买入逻辑不成立，无论此时是浮亏还是浮盈，都应该果断卖出。</li></ol></li><li><ol start="2"><li>股价被极度高估。高估并不是卖出标准，股价被极度高估甚至疯狂才值得卖出。对于非常优秀的公司，也可以作为“永恒的持股”​，只要潜力不发挥出来就永不卖出。</li></ol></li><li><ol start="3"><li>公司基本面恶化。因为某些不可逆转的经营失误或外部环境的变化导致公司原有的商业模式不再成立，或者成长空间、护城河受损，此时应该卖出。当然这里要区分短期业绩回落与长期业绩下滑。</li></ol></li><li><ol start="4"><li>发现了更有确定性、更好的标的。当然，除非遇到明显更好的标的，这个卖出标准一般不用。</li></ol></li></ul></li></ul></li><li><ol start="3"><li>卖出动作是否受到心理偏误的影响</li></ol><ul><li>错误卖出标准： <ul><li>是否只是因为股价涨太多而卖出？</li><li>是否只是因为无法承受股价下跌而卖出？</li><li>卖出决定是否受到了买入成本价的影响？</li></ul></li><li>买入价、浮盈、浮亏程度与是否应该卖出没有任何关联。</li></ul></li><li><ol start="4"><li>是否触发了新的买入标准</li></ol><ul><li>少数优秀公司股价大幅上涨后反而具备了更大的投资价值，​“好公司的股价可能越涨越便宜”​。</li><li>公司遇到熊市或暂时性的“黑天鹅”事件导致估值大幅下滑。在这些情况下，我们重新执行研究阶段和交易阶段的检查清单。</li><li>如果触发了新的买入标准，不应该受到最初买入价格锚定效应的影响。</li></ul></li></ul><p>从以上的检查清单，我们可以看出，检查清单的主要任务是各种排除和拒绝。拒绝买，除非不得不买，拒绝卖，直到不得不卖。检查清单从来都不是大而全的操作手册，而是理性选择后的思维方式，帮助我们程序化地识别并避免各种严重风险。</p><p>史学泰斗吕思勉先生提出史学研究有四大任务：搜寻过往的事实；加以解释；用以理解当下；因以推测未来。</p><p>研究企业的任务，与之类似。一是搜寻以往的经营行为和经营绩效；二是对过去的经营绩效加以解释；三是理解企业当下的环境、优势和问题；四是预测企业未来的经营绩效，会不变、更差还是更佳，或者企业未来采取哪些经营行为将使得经营绩效更差或是更佳。这四个环节中，重点和难点在于解释公司过去为何优秀，和预测未来三五年或更长时间公司的情况。理解过去是预测未</p><p>——《投资至简：从原点出发构建价值投资体系》第三章 第一节 投资的检查清单思维</p><h2 id="长期持有" tabindex="-1">长期持有 <a class="header-anchor" href="#长期持有" aria-label="Permalink to &quot;长期持有&quot;">​</a></h2><p>其实 A 股里很多的白马股、长牛股，多少年前就众人皆知。很多人也多多少少买过，但是真正从这些白马股、长牛股上赚取了大量绝对回报的人是很少的。原因无非还是那几条：怕继续跌不敢下手买，看见已经涨了怕回调不敢买，涨了心慌天天都想卖，涨了跌下来要卖，跌了涨回去也要卖，嫌涨得慢等不了还是要卖，躲回调做波段给做飞了，遇到鬼故事又给吓出来……</p><p>这几条原因，其实可以归结为两条—一是对公司价值没有建立足够的信心。二是对市场波动没有形成正确的认识。</p><p>那么，长期持有一家公司的股票是一种怎样的体验呢?</p><ol><li><strong>买入的时候，要有充分的安全边际</strong><br> 我们的买入，是建立在风险已经完全释放甚至过度释放的位置。即使估值短期进一步下滑，我们也很难遭受毁灭性的打击。如果我们判断正确，那么我们未来的盈利就很可观了。</li><li><strong>忘掉买入价</strong><br> 在买完以后，买入价就没有什么意义了。股价已经相对于买入价涨了多少从来都不应该是卖出的理由。也许股价已经相对于我们的买入价翻了一倍，但是这个时候相比我们当初的买入点可能反而是更好的一个买入点。</li><li><strong>不要有预期收益</strong><br> 不要有预期收益就是说对股票能在未来哪个时间能涨到多少是完全不知道的。买入的逻辑是随着企业经营的画卷逐步展开而得到印证。只要买入逻辑在经营和财报上都取得了印证，那么我们就可以安坐下来，继续观察事情下一步的发展。</li><li><strong>动态检视对企业价值的评估不是一劳永逸的事情。</strong><br> 随着时间的推移，企业面临的市场环境、内部的经营管理也在发生持续的变化。我们要不断衡量企业的内在价值，不断衡量当前股价与企业当前内在价值的关系，而不是与我们买入价的关系。​“三聚氰胺事件”发生后的几年，牛奶行业的格局和各家企业的发展态势甚至命运都发生了很大的变化。</li><li><strong>没有确定性的东西，不必提前忧虑和事后后悔新的黑天鹅事件、事后也找不出任何理由的市场大幅波动，都有可能会在持股期间发生。</strong><br> 遇到这种情况的时候，一些人都会后悔，​“早知道我就先卖了”​。可是另外一个问题是：​“我有可能预测到吗?”答案通常是没有可能。既然没有可能，就坦然接受它好了，把它当成投资的一部分。我们需要做的是分清这是市场波动还是公司出了问题。公司出的问题会不会对公司带来实质性的影响。</li><li><strong>正确面对长期盘整甚至回撤</strong><br> 长期盘整和回撤，特别是大幅度回撤，都不会是一件让人愉快的事情。但是仅仅因为不愿意参加盘整只想抓“主升浪”​，因为预测市值要回撤或者因为已经回撤而卖出股票，都不是明智的选择。在很多情况下，盘整和回撤仅仅是上涨的一个不可或缺的组成部分。很多优秀公司股票的走势已经证明，大部分时候股价都是在盘整甚至下跌。股价向内在价值回归的主要升幅都是在比较短的时间内完成的。但是为了百分之百抓住这些主要升幅，我们最靠谱的办法是全程在场等待，虽然笨但足够有效。我们持有伊利的过程中遇到过两次股价近腰斩的回撤，但这并不能影响什么。</li></ol><p>长期持有一家公司的股票其实一点儿都不波澜壮阔，一点儿也不心惊肉跳。它只是持续地做正确的决策之后的一个慢慢呈现的、自然的结果。</p><p>——《投资至简：从原点出发构建价值投资体系》第三章 第四节 伊利股份： “三聚氰胺事件”后的困境反转</p>',23)])])}const g=i(r,[["render",s]]);export{p as __pageData,g as default};
